package org.gepnic.doors.masterapi.inbound;
import org.gepnic.doors.inbound.*;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.stereotype.Service;
import java.nio.charset.StandardCharsets;
import java.util.*;
import java.io.*;
import java.util.zip.*;

@Service
public class WriteIntegrationService {
 @org.springframework.beans.factory.annotation.Value("${doors.write-sdk.uat-identity-path:}")
 private String uatIdentityPath="";
 @org.springframework.beans.factory.annotation.Value("${doors.write-sdk.uat-wallet-properties:}")
 private String uatWalletProperties="";
 @org.springframework.beans.factory.annotation.Autowired private WriteEncryptionKeys encryptionKeys;
 public byte[] sdk(long id,String base,String profile)throws Exception{
  if(!Set.of("UAT","PROD").contains(profile))throw new IllegalArgumentException("Choose UAT or PROD SDK");
  var d=new LinkedHashMap<>(details(id));d.put("encryption",encryptionKeys.active());return WriteSdkRelease.create(sdk(id,base),d,base,profile,uatIdentityPath,uatWalletProperties);
 }
 public String sdkDownloadName(long id,String profile){return WriteSdkRelease.sourceFile(details(id),profile).replaceFirst("\\.java$","")+".zip";}
 private final JdbcTemplate db;
 public WriteIntegrationService(JdbcTemplate db){this.db=db;}
 public Map<String,Object> details(long id){var rows=db.queryForList("SELECT r.id,r.service_code,r.instance_id,r.agent_id,r.client_id,r.enabled,r.max_versions,r.protocol_version,c.contract_version,c.title,c.sample_json,c.definition_json,c.definition_hash,d.status AS verification_status,d.verified_at,e.client_name FROM inbound_write_routes r JOIN write_deployments d ON d.id=r.deployment_id JOIN write_contracts c ON c.id=d.contract_id JOIN external_api_clients e ON e.client_id=r.client_id WHERE r.id=? AND c.status='APPROVED'",id);if(rows.isEmpty())throw new IllegalArgumentException("An approved mapped contract is required");return rows.getFirst();}
 public Map<String,Object> guide(long id){var d=details(id);var result=new LinkedHashMap<>(d);result.remove("definition_json");var spec=JsonWriteDefinition.from(d.get("definition_json"));result.put("automaticVersioning",JsonWriteDefinition.automatic(spec));result.put("businessKeys",spec.businessKey());result.put("fields",spec.fields());result.put("endpoint","/api/v1/inbound/"+d.get("service_code"));result.put("transportSchemaVersion",1);result.put("encryption",WriteCrypto.MODE);result.put("signingFormat","DOORS-INBOUND-AES\\n{service}\\n{instance}\\n{requestId}\\n1\\n{expectedRecordVersion}\\n{unixTimestamp}\\n{contractVersion}\\n{sha256OfExactUtf8Envelope}");return result;}
 public String scopeSql(long id,boolean enable){var d=details(id);var spec=JsonWriteDefinition.from(d.get("definition_json"));return "-- DBA: client "+d.get("client_id")+" may write all business keys for service "+spec.service()+" in this instance only.\nBEGIN;\nINSERT INTO "+JsonWriteDefinition.schema(spec)+"."+JsonWriteDefinition.object(spec,"service_grant")+" (instance_id,client_id,enabled) VALUES ("+literal(d.get("instance_id").toString())+","+((Number)d.get("client_id")).longValue()+","+enable+") ON CONFLICT(instance_id,client_id) DO UPDATE SET enabled=EXCLUDED.enabled;\nCOMMIT;\n";}
 public String scopeUpgrade(long id){return JsonWriteDefinition.scopeUpgradeDdl(JsonWriteDefinition.from(details(id).get("definition_json")));}
 private String literal(String value){return "E'"+value.replace("\\","\\\\").replace("'","''")+"'";}
 public Map<String,Object> openapi(long id)throws Exception{var d=details(id);List<Object> parameters=new ArrayList<>();for(var e:Map.of("X-DOORS-Instance-ID",d.get("instance_id"),"X-DOORS-Protocol-Version",d.get("protocol_version"),"X-DOORS-Contract-Version",d.get("contract_version"),"X-DOORS-Schema-Version",1,"X-DOORS-Expected-Version",JsonWriteDefinition.automatic(JsonWriteDefinition.from(d.get("definition_json")))?-1:0,"Idempotency-Key","generate-and-retain-a-UUID","X-DOORS-Timestamp","Unix seconds","X-DOORS-Signature","RSA-SHA256 signature").entrySet())parameters.add(Map.of("name",e.getKey(),"in","header","required",true,"schema",Map.of("type","string","default",e.getValue().toString())));
  parameters.add(Map.of("name","X-DOORS-Encryption","in","header","required",true,"schema",Map.of("type","string","const",WriteCrypto.MODE,"default",WriteCrypto.MODE)));
  var operation=Map.of("summary","Submit "+d.get("title"),"description","Standard AES-256-GCM encrypted request and response. The x-doors-plaintext-schema/example describe the decrypted business document. Private keys remain on the caller's device. Reuse the request ID, payload and expected version after an uncertain result. JSON contract "+d.get("contract_version")+"; independent record versions.","security",List.of(Map.of("ApiKey",List.of())),"parameters",parameters,"requestBody",Map.of("required",true,"content",Map.of("application/json",Map.of("schema",encryptedSchema(),"x-doors-plaintext-schema",WriteOnboardingDocuments.requestSchema(JsonWriteDefinition.from(d.get("definition_json"))),"x-doors-plaintext-example",InboundProtocol.JSON.readTree(d.get("sample_json").toString())))),"responses",encryptedResponses());
  return Map.of("openapi","3.1.0","info",Map.of("title",d.get("title"),"version",d.get("contract_version").toString()),"paths",Map.of("/api/v1/inbound/"+d.get("service_code"),Map.of("post",operation)),"components",Map.of("securitySchemes",Map.of("ApiKey",Map.of("type","apiKey","in","header","name","X-API-KEY"))));
 }
 public byte[] sdk(long id)throws Exception{return sdk(id, "");}
 public byte[] sdk(long id,String apiBaseUrl)throws Exception{
  if(apiBaseUrl==null)apiBaseUrl="";
  if(!apiBaseUrl.isBlank()){var uri=java.net.URI.create(apiBaseUrl);if(!"https".equals(uri.getScheme())||uri.getHost()==null||uri.getUserInfo()!=null||uri.getQuery()!=null||uri.getFragment()!=null||!uri.getPath().endsWith("/api/v1"))throw new IllegalArgumentException("Use the approved HTTPS machine API base ending in /api/v1");}
  var d=details(id);
  var pinned=JsonWriteDefinition.from(d.get("definition_json"));
  if(!"VERIFIED".equals(d.get("verification_status"))||!JsonWriteDefinition.hash(pinned).equals(d.get("definition_hash")))throw new IllegalArgumentException("Verify the pinned approved schema before downloading its SDK and documents");
  String apiKey=db.queryForObject("SELECT api_key FROM external_api_clients WHERE client_id=?",String.class,d.get("client_id"));
  if(apiKey==null||apiKey.isBlank())throw new IllegalArgumentException("Client API key is missing");var bytes=new ByteArrayOutputStream();try(var zip=new ZipOutputStream(bytes,StandardCharsets.UTF_8)){
  try(var in=getClass().getResourceAsStream("/inbound/sdk/WriteClient.java")){if(in==null)throw new IllegalStateException("SDK template missing");String source=new String(in.readAllBytes(),StandardCharsets.UTF_8);try(var crypto=getClass().getResourceAsStream("/inbound/sdk/WriteCrypto.java.txt")){String helper=new String(crypto.readAllBytes(),StandardCharsets.UTF_8);String imports=helper.lines().filter(l->l.startsWith("import ")).collect(java.util.stream.Collectors.joining("\n"));source=imports+"\n"+source+"\n"+helper.lines().filter(l->!l.startsWith("import ")).collect(java.util.stream.Collectors.joining("\n"));}entry(zip,"WriteClient.java",source);}
  for(String asset:List.of("build-doors-write-kit.ps1","readme-enduser-uat.txt","readme-enduser-prod.txt")){
   try(var in=getClass().getResourceAsStream("/inbound/sdk/"+asset)){if(in==null)throw new IllegalStateException("SDK asset missing: "+asset);entry(zip,asset,new String(in.readAllBytes(),StandardCharsets.UTF_8));}
  }
  for(var document:WriteOnboardingDocuments.create(d,apiBaseUrl).entrySet())entry(zip,document.getKey(),document.getValue());
  entry(zip,"sample.json",d.get("sample_json").toString());
  entry(zip,"openapi.json",InboundProtocol.JSON.writerWithDefaultPrettyPrinter().writeValueAsString(openapi(id)));
  entry(zip,"doors-wallet.properties","# Set the approved HTTPS machine API base URL ending in /api/v1\nDOORS_API_BASE_URL="+propertyValue(apiBaseUrl)+"\nDOORS_SERVICE="+d.get("service_code")+"\nDOORS_INSTANCE="+d.get("instance_id")+"\nDOORS_AUTOMATIC_VERSIONING="+JsonWriteDefinition.automatic(JsonWriteDefinition.from(d.get("definition_json")))+"\nDOORS_PROTOCOL_VERSION=1\nDOORS_CONTRACT_VERSION="+d.get("contract_version")+"\n# This kit contains the selected client API key. Keep it private.\nDOORS_API_KEY="+propertyValue(apiKey)+"\nDOORS_WALLET_PATH=~/doors/security/doors-identity.p12\nDOORS_WALLET_ALIAS=\nDOORS_WALLET_PASS=\n# Optional: private CA / local development truststore. Blank path uses JVM defaults.\nDOORS_TRUSTSTORE_PATH=\nDOORS_TRUSTSTORE_PASS=\nDOORS_TRUSTSTORE_TYPE=PKCS12\n");
  entry(zip,"README.txt","DOORS WRITE SDK - Java 21 or newer\n\nSTART HERE: Open docs/index.html in a browser. This SDK includes contract-specific SDK instructions, JSON field dictionary and schema, response examples, direct API signing instructions and an onboarding checklist. The documents reflect the approved verified mapping at download time and contain no API key or private identity.\n\nRELEASE PREPARATION (same local packaging approach as read SDKs):\nUAT: powershell.exe -NoProfile -ExecutionPolicy Bypass -File ./build-doors-write-kit.ps1 -Profile UAT\nThe builder prompts for the UAT wallet password and bundles the local $HOME/doors/security/doors-identity.p12 with its public certificate and configured wallet. Use -WalletPath to select another test identity. Map the exported public certificate to this Write client before sharing/testing.\nProduction: powershell.exe -NoProfile -ExecutionPolicy Bypass -File ./build-doors-write-kit.ps1 -Profile PROD\nProduction ZIP excludes private identities and wallet passwords; end users place their identity under their home doors/security directory. Each release includes its profile-specific end-user README and an external SHA-256 file.\nA blank alias selects the sole private-key entry; an incorrect explicit alias is rejected with a clear message. ~/ paths expand to Java user.home.\n\nApplication/client ID: "+d.get("client_id")+"\nAPI protocol: 1\nJSON contract: "+d.get("contract_version")+"\nRecord version: independent, starting at 1.\n\n1. API key, service, instance and versions are prefilled for the selected client. Verify the API base URL, then set your local PKCS12 path, alias and password. Prefer environment variables for secrets.\n2. Keep your PKCS12 identity on your computer; upload only its public certificate in Write Services.\n3. Have the DBA apply the service/instance scope SQL generated from Write access scope. No per-agreement grants are required.\n4. Enable the verified service mapping.\n5. New automatic-versioning contracts: java WriteClient.java sample.json\n   DOORS assigns the next version. Identical JSON returns UNCHANGED without a new snapshot. The configured client/service maximum counts all versions of that record; unchanged data and retries do not consume it. VERSION_LIMIT_REACHED means contact the DOORS Administrator.\n6. On timeout, rerun the same command and original file. The SDK retains the UUID internally until a definite result. Do not delete .doors-write-requests while a result is unknown. Resolve a pending submission before changing the file.\nLegacy contracts/SDK syntax remains: java WriteClient.java sample.json expectedRecordVersion [request-UUID]. For legacy retries reuse all original inputs. The generated wallet indicates whether automatic versioning is supported.\n\nThe SDK sends a signed request over HTTPS. A successful response is 201; an identical replay is 200. A 409 requires checking the stored version, not blindly incrementing it.\nThe original payload file is not rewritten. The SDK does not generate keys or create database objects.\nHTTPS trust: leave DOORS_TRUSTSTORE_PATH blank to use the JVM default truststore (or existing JVM -D settings). For local development or a private CA, set DOORS_TRUSTSTORE_PATH=local-dev-truststore.p12, DOORS_TRUSTSTORE_PASS=<truststore-password>, and DOORS_TRUSTSTORE_TYPE=PKCS12 in doors-wallet.properties. Use JKS for a JKS store. Environment variables with these names override wallet values; a configured path overrides JVM -D truststore settings. Use forward slashes in Windows paths, e.g. C:/Users/User/doors/security/truststore.p12; relative paths resolve from the working directory. Use a truststore supplied by your administrator; it replaces the default truststore for this process. Certificate and hostname verification remain enabled. No truststore or truststore password is bundled. The simple command for new contracts is: java WriteClient.java sample.json. The signing PKCS12 identity and HTTPS truststore have different purposes.\nDo not set default_transaction_read_only on the write connection.\nThis kit contains the registered API key. Share only with the authorised application owner. No private key or wallet password is included.\n");
 }return bytes.toByteArray();}
 private static Map<String,Object> encryptedResponses(){var result=new LinkedHashMap<String,Object>();for(var entry:Map.of("200","Unchanged or replayed","201","Stored","403","Access denied","409","Version limit or record/idempotency conflict","422","Invalid request","504","Result unknown; retry original UUID and plaintext").entrySet())result.put(entry.getKey(),Map.of("description",entry.getValue()+". Accepted encrypted requests return an encrypted envelope; pre-authentication and proxy errors can be plaintext.","headers",Map.of("X-DOORS-Encryption",Map.of("schema",Map.of("type","string","const",WriteCrypto.MODE)),"X-DOORS-Response-Signature",Map.of("schema",Map.of("type","string"))),"content",Map.of("application/json",Map.of("schema",encryptedSchema()))));return result;}
 public static Map<String,Object> encryptedSchema(){return Map.of("type","object","additionalProperties",false,"required",List.of("kid","encryptedKey","iv","secureData"),"description","AES-256-GCM envelope. RSA-OAEP SHA-256 with MGF1 SHA-256 wraps the fresh AES key. Standard Base64; IV 12 bytes; secureData includes the 16-byte GCM tag. X-DOORS-Signature authenticates the exact envelope and metadata. See x-doors-plaintext-schema for the business contract.","properties",Map.of("kid",Map.of("type","string","pattern","^[A-Za-z0-9_-]{1,100}$"),"encryptedKey",Map.of("type","string","contentEncoding","base64"),"iv",Map.of("type","string","contentEncoding","base64"),"secureData",Map.of("type","string","contentEncoding","base64")));}
 private String propertyValue(String value){return value.replace("\\","\\\\").replace("\n","\\n").replace("\r","\\r").replace("\t","\\t");}
 private void entry(ZipOutputStream zip,String name,String text)throws IOException{zip.putNextEntry(new ZipEntry(name));zip.write(text.getBytes(StandardCharsets.UTF_8));zip.closeEntry();}
}
